#!/usr/bin/env node
/**
 * make-cf-bundle.mjs — builds deploy/cf-bundle.json, the exact site payload
 * for the Cloudflare Worker deployment (content transported via the Cloudflare
 * connector; text is gzipped, binaries stay base64).
 *
 * The Cloudflare build uses Google Fonts CDN for webfonts; the self-hosted
 * fonts (tools/fetch-fonts.mjs) are used by the local / preview build.
 *
 * Usage: node tools/make-cf-bundle.mjs
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { gzipSync } from 'node:zlib';
import path from 'node:path';

const root = process.cwd();
const out = path.join(root, 'deploy');
await mkdir(out, { recursive: true });

const CDN_FONTS_CSS =
  '/* Webfonts via Google Fonts CDN (Cloudflare deployment).\n' +
  '   Self-contained builds use assets/fonts.css generated by tools/fetch-fonts.mjs. */\n' +
  "@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Thai:wght@400;500;600&family=Noto+Sans+Lao:wght@400;600&display=swap');\n";

const TEXT = {
  'index.html': 'text/html; charset=utf-8',
  'assets/styles.css': 'text/css; charset=utf-8',
  'assets/i18n.js': 'application/javascript; charset=utf-8',
  'assets/app.js': 'application/javascript; charset=utf-8',
  'assets/fonts.css': 'text/css; charset=utf-8',
  'assets/icon.svg': 'image/svg+xml',
  'manifest.webmanifest': 'application/manifest+json',
  'sw.js': 'application/javascript; charset=utf-8'
};

const BIN = {
  'assets/icon-192.png': 'image/png',
  'assets/icon-512.png': 'image/png'
};

const files = {};
for (const [f, t] of Object.entries(TEXT)) {
  const body = (f === 'assets/fonts.css') ? CDN_FONTS_CSS : await readFile(path.join(root, f), 'utf8');
  files[f] = { t, e: 'gzip', b: gzipSync(Buffer.from(body, 'utf8')).toString('base64') };
}
for (const [f, t] of Object.entries(BIN)) {
  files[f] = { t, e: 'raw', b: (await readFile(path.join(root, f))).toString('base64') };
}

await writeFile(path.join(out, 'fonts.cdn.css'), CDN_FONTS_CSS, 'utf8');
const bundle = { v: 'temp-2026-10a', files };
const json = JSON.stringify(bundle);
await writeFile(path.join(out, 'cf-bundle.json'), json, 'utf8');

console.log('[bundle]', Object.keys(files).length, 'files — json:', (json.length / 1024).toFixed(1), 'KB');
for (const [f, o] of Object.entries(files)) {
  console.log('  ' + f + '  [' + o.e + ']  ' + (o.b.length / 1024).toFixed(1) + ' KB b64');
}
